#pragma once
#include "cpu.h"
/* Tables generated by recomp.py for one translated module (table.c, import_stubs.c). */
struct func_entry { u32 addr; guest_fn fn; };
struct import_entry { u32 slot; const char *dll; const char *name; guest_fn fn; };  /* fn: shim or weak stub */
struct export_entry { const char *name; u32 ordinal; u32 addr; };
struct guest_module {
    const char *name;
    const struct func_entry *funcs;      /* sorted by addr */
    unsigned nfuncs;
    const struct import_entry *imports;  /* sorted by slot */
    unsigned nimports;
    const struct export_entry *exports;  /* not forwarded */
    unsigned nexports;
    u32 entry, base, end;
    int is_dll;
};
